'use strict';
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.MIRWorkshopQuality=api})(typeof window==='object'?window:null,function(){
const clone=v=>JSON.parse(JSON.stringify(v));const text=v=>String(v??'').trim();const now=v=>v?new Date(v).toISOString():new Date().toISOString();const assert=(c,m)=>{if(!c)throw new Error(m)};const makeId=p=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
function conflict(e,a){const x=new Error(`Conflit de révision : attendu ${e}, actuel ${a}`);x.code='REVISION_CONFLICT';return x}
function createQualityState({organizationId='MIR',now:at}={}){return{schemaVersion:1,organizationId:text(organizationId)||'MIR',revision:1,reviews:[],events:[],createdAt:now(at),updatedAt:now(at)}}
function ensure(s,r){if(!Number.isInteger(r))throw new Error('expectedRevision requis');if(r!==s.revision)throw conflict(r,s.revision)}
function requiredChecks(job){const c=['quantity','material','color','drawing'];if(job.sourceSnapshot?.ruleExceptions?.length)c.push('exceptions');return c}
function reviewJob(state,job,input={},opts={}){ensure(state,opts.expectedRevision);assert(job?.id,'Tâche atelier requise');assert(job.status==='completed','La tâche doit être terminée avant contrôle qualité');assert(text(input.inspectorId),'Identité inspecteur requise');const checks={...(input.checks||{})};const req=requiredChecks(job);const missing=req.filter(k=>checks[k]!==true);const passed=input.passed===true;assert(!passed||missing.length===0,`Contrôles requis manquants : ${missing.join(', ')}`);const next=clone(state);next.revision+=1;next.updatedAt=now(opts.now);const review={id:makeId('qc'),jobId:job.id,releaseId:job.releaseId,itemId:job.itemId,inspectorId:text(input.inspectorId),passed,checks,requiredChecks:req,note:text(input.note),reviewedAt:next.updatedAt,status:passed?'passed':'rework_required'};next.reviews.push(review);next.events.push({kind:passed?'qc-passed':'qc-failed',jobId:job.id,reviewId:review.id,at:next.updatedAt,revision:next.revision});return next}
function latestReview(state,jobId){return clone([...state.reviews].reverse().find(r=>r.jobId===jobId)||null)}
function releaseQualitySummary(state,jobs,releaseId){const active=(jobs||[]).filter(j=>j.releaseId===releaseId&&j.status!=='cancelled');const details=active.map(j=>({jobId:j.id,status:j.status,review:latestReview(state,j.id)}));const incomplete=details.filter(x=>x.status!=='completed');const unreviewed=details.filter(x=>x.status==='completed'&&!x.review);const failed=details.filter(x=>x.review&&x.review.passed!==true);return{jobs:details.length,incomplete:incomplete.length,unreviewed:unreviewed.length,failed:failed.length,passed:details.filter(x=>x.review?.passed===true).length,readyForDispatch:details.length>0&&!incomplete.length&&!unreviewed.length&&!failed.length,details}}
function supersedeReview(state,job,input={},opts={}){const prev=latestReview(state,job?.id);assert(prev,'Aucun contrôle précédent');const next=reviewJob(state,job,input,opts);next.events.push({kind:'qc-review-superseded',jobId:job.id,previousReviewId:prev.id,newReviewId:next.reviews.at(-1).id,at:next.updatedAt,revision:next.revision});return next}
function serialize(s){return JSON.stringify(s,null,2)}function restore(raw){const s=typeof raw==='string'?JSON.parse(raw):clone(raw);assert(s?.schemaVersion===1&&Number.isInteger(s.revision),'Contrôle qualité invalide');s.reviews=Array.isArray(s.reviews)?s.reviews:[];s.events=Array.isArray(s.events)?s.events:[];return s}
return{createQualityState,requiredChecks,reviewJob,latestReview,releaseQualitySummary,supersedeReview,serialize,restore};
});
